(function(){
const enc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={paths:'경로와 현재 위치',commands:'파일 명령·리다이렉션',permissions:'권한과 umask',links:'하드 링크·심볼릭 링크',patterns:'패턴과 파이프',vi:'vi 모드·버퍼·저장',make:'Makefile 의존 관계'};
let currentPage=0,kind='paths',step=0,viScene='save',change='file2.c',cwd='/home/minsu',path='game/diablo3/play',mode=0o666,mask=0o022,pattern='c??';
const commands=[
 {cmd:'시작 전',files:{'a.txt':'Hello\nUNIX\n'},dirs:['work'],out:'현재 위치 /home/student. 아래 파일은 가상 파일입니다.',why:'프로세스의 실제 파일·폴더에는 접근하지 않습니다.'},
 {cmd:'mkdir notes',files:{'a.txt':'Hello\nUNIX\n'},dirs:['work','notes'],out:'',why:'notes 디렉토리를 만들었습니다. 현재 위치는 /home/student 그대로입니다.'},
 {cmd:'cp a.txt b.txt',files:{'a.txt':'Hello\nUNIX\n','b.txt':'Hello\nUNIX\n'},dirs:['work','notes'],out:'',why:'별도 파일 b.txt에 내용을 복사했습니다. 같은 inode를 가리키는 하드 링크와 다릅니다.'},
 {cmd:'mv b.txt notes/b.txt',files:{'a.txt':'Hello\nUNIX\n','notes/b.txt':'Hello\nUNIX\n'},dirs:['work','notes'],out:'',why:'복사본의 경로가 notes/b.txt로 바뀌었습니다.'},
 {cmd:'cat a.txt',files:{'a.txt':'Hello\nUNIX\n','notes/b.txt':'Hello\nUNIX\n'},dirs:['work','notes'],out:'Hello\nUNIX\n',why:'파일 내용이 표준 출력으로 흐릅니다. 파일 내용은 바뀌지 않습니다.'},
 {cmd:'cat a.txt > result.txt',files:{'a.txt':'Hello\nUNIX\n','notes/b.txt':'Hello\nUNIX\n','result.txt':'Hello\nUNIX\n'},dirs:['work','notes'],out:'',why:'셸이 stdout을 result.txt에 연결합니다. cat은 내용을 복사하고 터미널에는 출력하지 않습니다.'},
 {cmd:'cat a.txt >> result.txt',files:{'a.txt':'Hello\nUNIX\n','notes/b.txt':'Hello\nUNIX\n','result.txt':'Hello\nUNIX\nHello\nUNIX\n'},dirs:['work','notes'],out:'',why:'>>는 기존 결과 뒤에 추가합니다. >였다면 새 내용으로 절단·대체됩니다.'},
 {cmd:'rmdir notes',files:{'a.txt':'Hello\nUNIX\n','notes/b.txt':'Hello\nUNIX\n','result.txt':'Hello\nUNIX\nHello\nUNIX\n'},dirs:['work','notes'],out:'rmdir: notes: Directory not empty',why:'notes 안에 b.txt가 있으므로 제거가 실패합니다. 가상 파일 목록이 유지됩니다.'}
];
const vi={save:[
 ['vi test.txt','명령 모드','hello\n','hello\n','파일을 읽어 편집 버퍼를 만듭니다.'],['i','삽입 모드','hello\n','hello\n','입력한 문자가 이제 편집 데이터로 들어갑니다.'],['UNIX ','삽입 모드','UNIX hello\n','hello\n','커서 앞에 입력했습니다. 버퍼만 바뀌고 저장 파일은 그대로입니다.'],['Esc','명령 모드','UNIX hello\n','hello\n','명령 모드로 돌아갑니다.'],[':w','명령 모드','UNIX hello\n','UNIX hello\n','버퍼 내용을 저장 파일에 기록합니다.'],[':q','셸','UNIX hello\n','UNIX hello\n','저장되지 않은 변경이 없으므로 편집기를 나옵니다.'],['cat test.txt','셸','UNIX hello\n','UNIX hello\n','셸에서 저장된 파일 내용을 확인합니다.']
],undo:[
 ['시작','명령 모드','one\ntwo\n','one\ntwo\n','커서는 첫 줄에 있습니다.'],['dd','명령 모드','two\n','one\ntwo\n','첫 줄을 삭제합니다. 디스크 파일은 아직 바뀌지 않습니다.'],['u','명령 모드','one\ntwo\n','one\ntwo\n','삭제 작업을 취소합니다.'],['Ctrl-R','명령 모드','two\n','one\ntwo\n','현대 Vim에서 취소한 삭제를 다시 적용합니다. r과 다릅니다.'],[':q!','셸','one\ntwo\n','one\ntwo\n','미저장 변경을 버립니다. 저장 파일은 최초 내용입니다.']
],substitute:[
 ['시작 · 커서 1행','명령 모드','cat cat\ncat dog\n','cat cat\ncat dog\n','동일한 단어가 두 줄에 있습니다.'],[':s/cat/CAT/g','명령 모드','CAT CAT\ncat dog\n','cat cat\ncat dog\n','기본 범위는 현재 줄입니다. g는 첫 줄 안의 모든 일치를 바꿉니다.'],[':%s/cat/CAT/g','명령 모드','CAT CAT\nCAT dog\n','cat cat\ncat dog\n','%로 전체 줄을 지정합니다. 아직 저장하지 않았습니다.'],[':wq','셸','CAT CAT\nCAT dog\n','CAT CAT\nCAT dog\n','전체 버퍼를 저장하고 종료합니다.']
]};
function defaultKind(p){return p>=64?'make':p>=54?'vi':p>=40&&p<=41?'links':p>=34&&p<=39?'permissions':p===17||p===28||p===29||p>=42&&p<=48?'patterns':p>=11&&p<=33?'commands':'paths';}
function controls(max){return `<div class="sim-controls"><span class="step-label">단계 ${step} / ${max}</span><button id="w02-reset">처음부터</button><button id="w02-prev" ${step===0?'disabled':''}>이전</button><button class="primary" id="w02-next" ${step>=max?'disabled':''}>다음 단계</button></div>`;}
function normalize(base,input){let pieces=input.startsWith('/')?[]:base.split('/').filter(Boolean);const trace=[];for(const c of input.split('/')){if(!c||c==='.')continue;if(c==='..')pieces.pop();else pieces.push(c);trace.push({part:c,path:'/'+pieces.join('/')});}return{result:'/'+pieces.join('/'),trace};}
function permText(n){return[6,3,0].map(shift=>[4,2,1].map((b,i)=>n&(b<<shift)?'rwx'[i]:'-').join('')).join('');}
function makePlan(changed){const inputs=['file1.c','file2.c','file3.c','common_header.h'];const times=Object.fromEntries(inputs.map(x=>[x,1]));if(changed!=='none')times[changed]=4;const result=[];for(let i=1;i<=3;i++)if(times[`file${i}.c`]>2||times['common_header.h']>2)result.push(`file${i}.o`);return result.length?[...result,'user123']:[];}
function html(p){if(p!==currentPage){currentPage=p;kind=defaultKind(p);step=0;}return `<div id="w02-lab"><h2>2주차 실행 실험실</h2><div class="lab-top"><label>실험 선택<select id="w02-kind">${Object.entries(names).map(([k,n])=>`<option value="${k}" ${k===kind?'selected':''}>${n}</option>`).join('')}</select></label></div><div id="w02-body">${body()}</div><p class="lab-note">w02의 개념을 연결한 교육용 실험입니다. 원문의 화면을 그대로 실행한 것이 아니며 실제 셸·Vim·make는 실행하지 않습니다. 파일 변경과 삭제는 화면 안의 가상 상태에만 적용됩니다. 경로 실험은 심볼릭 링크·존재 여부·권한을 검사하지 않는 문자열 경로 모형입니다.</p></div>`;}
function body(){if(kind==='paths'){const n=normalize(cwd,path);return `<h3>경로의 구성요소를 한 단계씩 해석</h3><div class="w02-form-grid"><label>현재 작업 디렉토리<input id="w02-cwd" value="${enc(cwd)}"></label><label>찾을 경로<input id="w02-path" value="${enc(path)}"></label></div><button id="w02-resolve" class="primary">경로 계산</button><div class="flow-row section-rule"><div class="flow-box">${enc(cwd)}<small>현재 위치</small></div><span class="flow-arrow">→</span><div class="flow-box lit">${enc(step?n.trace[Math.min(step,n.trace.length)-1]?.path||n.result:(path.startsWith('/')?'/':cwd))}<small>지금까지 해석한 위치</small></div></div><ol>${n.trace.map((t,i)=>`<li class="${i===step-1?'w02-active':''}"><code>${enc(t.part)}</code> → ${enc(t.path)}</li>`).join('')}</ol><p class="narration">최종 절대 경로: <b>${enc(n.result)}</b><br>${path.startsWith('/')?'입력 경로가 /로 시작하므로 현재 위치와 무관하게 루트에서 출발합니다.':'입력 경로는 현재 위치에서 출발합니다. ..을 만나면 한 단계 올라갑니다.'}</p>${controls(n.trace.length)}`;}
if(kind==='commands'){const a=commands[step];return `<h3>명령 한 줄마다 파일 상태 확인</h3><div class="buffer">$ ${enc(a.cmd)}\n${enc(a.out)}</div><div class="w02-files"><div><h3>디렉토리</h3>${a.dirs.map(d=>`<div class="node">${enc(d)}/</div>`).join('')}</div><div><h3>파일과 내용</h3>${Object.entries(a.files).map(([f,t])=>`<div class="node"><b>${enc(f)}</b><pre>${enc(t)}</pre></div>`).join('')}</div></div><p class="narration">${enc(a.why)}</p>${controls(commands.length-1)}`;}
if(kind==='permissions'){const effective=mode&~mask&0o777;return `<h3>chmod와 생성 권한을 구분하기</h3><p class="lab-note">체크 상자는 요청 mode를 바꿉니다. umask는 생성할 때 적용하는 비트 제거 마스크입니다.</p><div class="w02-perms">${[6,3,0].map((sh,j)=>`<fieldset><legend>${['소유자 u','그룹 g','기타 o'][j]}</legend>${[4,2,1].map((b,i)=>`<label><input type="checkbox" data-perm="${b<<sh}" ${mode&(b<<sh)?'checked':''}> ${'rwx'[i]} (${b})</label>`).join('')}</fieldset>`).join('')}</div><div class="lab-top"><label>생성 시 umask<select id="w02-mask">${[0,0o022,0o027,0o077].map(m=>`<option value="${m}" ${m===mask?'selected':''}>${m.toString(8).padStart(4,'0')}</option>`).join('')}</select></label></div><div class="flow-row"><div class="flow-box">요청 ${mode.toString(8).padStart(4,'0')}<small>${permText(mode)}</small></div><span class="flow-arrow">&amp; ~</span><div class="flow-box">마스크 ${mask.toString(8).padStart(4,'0')}</div><span class="flow-arrow">→</span><div class="flow-box lit">생성 ${effective.toString(8).padStart(4,'0')}<small>${permText(effective)}</small></div></div><p class="narration">기존 파일에 chmod ${mode.toString(8).padStart(3,'0')}를 적용하는 경우의 권한은 <b>${permText(mode)}</b>입니다. 위 생성 결과와 다를 수 있습니다. umask가 요청에 없던 실행 권한을 만들어 내지는 않습니다.</p>`;}
if(kind==='links'){const cmds=['시작: file1','ln file1 file2','ln -s file1 linkfile','file2로 내용 변경','rm file1'];const data=step>=3?'NEW':'DATA';return `<h3>같은 inode와 경로 참조의 차이</h3><div class="buffer">$ ${enc(cmds[step])}</div><div class="flow-row section-rule"><div><h3>디렉토리 이름</h3>${step<4?'<div class="flow-box lit">file1 → #14378</div>':''}${step>=1?'<div class="flow-box lit">file2 → #14378</div>':''}${step>=2?'<div class="flow-box">linkfile → #14394</div>':''}</div><span class="flow-arrow">→</span><div><div class="flow-box lit">inode #14378<small>링크 수 ${step===0||step===4?1:2} · 내용 ${data}</small></div>${step>=2?`<div class="flow-box">inode #14394<small>심볼릭 링크 내용: file1</small><small>${step===4?'file1 이름이 없어 연결 대상 없음':'file1 경로를 다시 해석'}</small></div>`:''}</div></div><p class="narration">${['일반 파일 하나와 그 이름이 있습니다.','file2는 새 이름이지만 같은 inode를 참조합니다. 링크 수가 2가 됩니다.','심볼릭 링크는 별도 inode를 갖고 파일 이름 경로를 담습니다.','file2로 쓴 내용은 같은 inode의 데이터이므로 file1로 읽어도 NEW입니다.','file1을 지워도 file2는 데이터를 유지합니다. linkfile은 삭제한 이름을 가리켜 dangling link가 됩니다.'][step]}</p>${controls(4)}`;}
if(kind==='patterns'){const files=['can','cnn','cmd','cat.txt','a.txt','z.txt',',.txt','character'];let matched=[];let why='이름 패턴은 셸에서 확장되는 단순 ASCII 예시입니다.';if(pattern==='c??')matched=files.filter(f=>/^c..$/.test(f));else if(pattern==='*.txt')matched=files.filter(f=>f.endsWith('.txt'));else if(pattern==='[a,z]*'){matched=files.filter(f=>/^[a,z]/.test(f));why='대괄호 목록에는 a, 쉼표, z 세 문자가 들어 있습니다. 범위는 [a-z]처럼 씁니다.';}else{matched=files.filter(f=>f.startsWith('a')||f.startsWith('ch'));why='Bash가 {a,ch}를 두 패턴 a*와 ch*로 확장한 뒤 이름 매칭을 수행합니다.';}return `<h3>패턴 확장 결과 예측</h3><label class="w02-label">패턴<select id="w02-pattern">${['c??','*.txt','[a,z]*','{a,ch}*'].map(p=>`<option ${p===pattern?'selected':''}>${p}</option>`).join('')}</select></label><div class="topic-links">${files.map(f=>`<span class="flow-box ${matched.includes(f)?'lit':''}">${enc(f)}</span>`).join('')}</div><div class="buffer">$ ls ${enc(pattern)}\n${enc(matched.join('  '))}</div><p class="narration">${why}</p><h3 class="section-rule">파이프는 문자열 흐름을 연결</h3><div class="flow-row"><div class="flow-box">목록 출력</div><span class="flow-arrow">→ stdout | stdin →</span><div class="flow-box">grep -F '.txt'</div><span class="flow-arrow">→</span><div class="flow-box lit">${files.filter(f=>f.includes('.txt')).join(' · ')}</div></div><p class="lab-note">실제 파일명 처리에서 ls 출력 파싱의 모든 문제를 재현하지 않는 설명용 목록입니다. grep은 입력 줄에서 패턴을 검색하고, 셸의 glob과 같은 문법이 아닙니다.</p>`;}
if(kind==='vi'){const a=vi[viScene][step];return `<h3>현재 모드와 저장 여부 추적</h3><label class="w02-label">vi 예제<select id="w02-vi-scene"><option value="save" ${viScene==='save'?'selected':''}>입력 → Esc → 저장 → 종료</option><option value="undo" ${viScene==='undo'?'selected':''}>dd → undo → redo → 버리기</option><option value="substitute" ${viScene==='substitute'?'selected':''}>현재 줄 치환과 전체 파일 치환</option></select></label><div class="buffer">입력: ${enc(a[0])}\n현재 상태: ${enc(a[1])}</div><div class="w02-files"><div class="panel"><div class="panel-title">편집 버퍼 ${a[2]!==a[3]?'· 미저장 변경 있음':''}</div><pre class="w02-editor">${enc(a[2])}</pre></div><div class="panel"><div class="panel-title">저장된 test.txt</div><pre class="w02-editor">${enc(a[3])}</pre></div></div><p class="narration">${enc(a[4])}</p>${controls(vi[viScene].length-1)}<div class="concept-callout">u = undo / Ctrl-R = redo / r = 한 문자 변경<br>n = 검색 반복 / . = 마지막 변경 반복<br>:s/old/new/g = 현재 줄 / :%s/old/new/g = 전체 줄</div>`;}
const plan=makePlan(change),done=plan.slice(0,step);return `<h3>수정한 파일이 어디까지 영향을 줄까요?</h3><label class="w02-label">변경한 파일<select id="w02-change">${['none','file1.c','file2.c','file3.c','common_header.h'].map(x=>`<option value="${x}" ${x===change?'selected':''}>${x==='none'?'변경 없음':x}</option>`).join('')}</select></label><p class="lab-note">기존 시각: 소스·헤더 1, 객체 2, 실행 파일 3. 선택한 입력의 시각을 4로 올립니다. 기본 목표는 user123이며 clean은 실행하지 않습니다.</p><div class="w02-dag"><div>${[1,2,3].map(i=>`<div class="node ${change===`file${i}.c`?'changed':''}">file${i}.c · t=${change===`file${i}.c`?4:1}</div>`).join('')}<div class="node ${change==='common_header.h'?'changed':''}">common_header.h · t=${change==='common_header.h'?4:1}<small>세 객체 모두에 의존 간선</small></div></div><div class="flow-arrow">→</div><div>${[1,2,3].map(i=>`<div class="node ${plan.includes(`file${i}.o`)?'changed':''}">file${i}.o<br>${done.includes(`file${i}.o`)?'재컴파일 완료':plan.includes(`file${i}.o`)?'갱신 필요':'최신 · 생략'}</div>`).join('')}</div><div class="flow-arrow">→</div><div class="node ${plan.includes('user123')?'changed':''}">user123<br>${done.includes('user123')?'다시 링크 완료':plan.includes('user123')?'객체 갱신 후 링크':'최신 · 생략'}</div></div><div class="buffer">${done.map(x=>x==='user123'?'cc -o user123 file1.o file2.o file3.o':`cc -c ${x.replace('.o','.c')} -o ${x}`).join('\n')||'아직 실행한 명령이 없습니다.'}</div><p class="narration">${plan.length?`필요한 작업: ${plan.join(' → ')}. ${step===plan.length?'선택한 변경에 필요한 빌드가 완료되었습니다.':'다음 단계로 필요한 recipe만 수행합니다.'}`:'전제 파일이 더 새롭지 않고 모든 결과가 존재하므로 갱신할 작업이 없습니다.'}</p>${controls(plan.length)}<details class="section-rule"><summary>변수명을 일관되게 고친 대응 Makefile</summary><pre class="original-text">${enc('BUILD = user123\nCC = cc\nCFLAGS = -Wall -O2\nOBJECTS = file1.o file2.o file3.o\n\n.PHONY: all clean\nall: $(BUILD)\n$(BUILD): $(OBJECTS)\n\t$(CC) -o $@ $^\n%.o: %.c common_header.h\n\t$(CC) $(CFLAGS) -c $< -o $@\nclean:\n\trm -f $(OBJECTS) $(BUILD)\n')}</pre><p class="lab-note">원문 68~72쪽의 의도를 설명하는 교정 예제입니다. 원문을 그대로 전사한 코드가 아닙니다. 실제 탭을 사용합니다.</p></details>`;
}
function redraw(){document.querySelector('#w02-body').innerHTML=body();bind();}
function bind(){const $=s=>document.querySelector(s);if(!$('#w02-lab'))return;if($('#w02-kind'))$('#w02-kind').onchange=e=>{kind=e.target.value;step=0;redraw();};if($('#w02-next'))$('#w02-next').onclick=()=>{step++;redraw();};if($('#w02-prev'))$('#w02-prev').onclick=()=>{step=Math.max(0,step-1);redraw();};if($('#w02-reset'))$('#w02-reset').onclick=()=>{step=0;redraw();};if($('#w02-resolve'))$('#w02-resolve').onclick=()=>{const c=$('#w02-cwd').value.slice(0,160);cwd=c.startsWith('/')?c:'/home/minsu';path=$('#w02-path').value.slice(0,160);step=0;redraw();};document.querySelectorAll('[data-perm]').forEach(el=>el.onchange=()=>{const bit=+el.dataset.perm;mode=el.checked?mode|bit:mode&~bit;redraw();});if($('#w02-mask'))$('#w02-mask').onchange=e=>{mask=+e.target.value;redraw();};if($('#w02-pattern'))$('#w02-pattern').onchange=e=>{pattern=e.target.value;redraw();};if($('#w02-vi-scene'))$('#w02-vi-scene').onchange=e=>{viScene=e.target.value;step=0;redraw();};if($('#w02-change'))$('#w02-change').onchange=e=>{change=e.target.value;step=0;redraw();};}
window.W02={html,bind,normalize,makePlan,permText};
})();
